#pragma once

inline int clamp_int(int v, int lo, int hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

inline float clamp_float(float v, float lo, float hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

inline double clamp_double(double v, double lo, double hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

test_setup_files.test_clamp.cpp:
#include "clamp.h"
#include <cassert>
#include <iostream>

int main() {
    assert(clamp_int(5, 0, 10) == 5);
    assert(clamp_int(-5, 0, 10) == 0);
    assert(clamp_int(15, 0, 10) == 10);

    assert(clamp_float(-1.5f, 0.0f, 1.0f) == 0.0f);
    assert(clamp_float(0.5f, 0.0f, 1.0f) == 0.5f);
    assert(clamp_float(2.5f, 0.0f, 1.0f) == 1.0f);

    assert(clamp_double(-100.0, -10.0, 10.0) == -10.0);
    assert(clamp_double(0.0, -10.0, 10.0) == 0.0);
    assert(clamp_double(100.0, -10.0, 10.0) == 10.0);

    std::cout << "PASS" << std::endl;
    return 0;
}

