#pragma once

template <typename T>
inline T clamp_value(T v, T lo, T hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

inline int clamp_int(int v, int lo, int hi) { return clamp_value<int>(v, lo, hi); }
inline float clamp_float(float v, float lo, float hi) { return clamp_value<float>(v, lo, hi); }
inline double clamp_double(double v, double lo, double hi) { return clamp_value<double>(v, lo, hi); }

